using System;
using System.Globalization;
using System.IO;
using System.Text;
using System.Threading.Tasks;

public static class Program
{
    public static void Main(string[] args)
    {
        int n = int.Parse(args[0], CultureInfo.InvariantCulture);
        int rowBytes = (n + 7) / 8;
        byte[] bitmap = new byte[checked(rowBytes * n)];

        double scale = 2.0 / n;
        double[] realCoordinates = new double[n];

        for (int x = 0; x < n; x++)
            realCoordinates[x] = x * scale - 1.5;

        Parallel.For(0, n, y =>
        {
            double ci = y * scale - 1.0;
            int rowOffset = y * rowBytes;
            int bits = 0;
            int bitCount = 0;
            int outputIndex = rowOffset;

            for (int x = 0; x < n; x++)
            {
                double cr = realCoordinates[x];
                double zr = 0.0;
                double zi = 0.0;
                double zr2 = 0.0;
                double zi2 = 0.0;
                int iteration = 0;

                while (iteration < 50)
                {
                    zi = 2.0 * zr * zi + ci;
                    zr = zr2 - zi2 + cr;
                    zr2 = zr * zr;
                    zi2 = zi * zi;
                    iteration++;

                    if (zr2 + zi2 > 4.0)
                        break;
                }

                bits <<= 1;
                if (zr2 + zi2 <= 4.0)
                    bits |= 1;

                bitCount++;

                if (bitCount == 8)
                {
                    bitmap[outputIndex++] = (byte)bits;
                    bits = 0;
                    bitCount = 0;
                }
            }

            if (bitCount != 0)
                bitmap[outputIndex] = (byte)(bits << (8 - bitCount));
        });

        Stream output = Console.OpenStandardOutput();
        byte[] header = Encoding.ASCII.GetBytes(
            "P4\n" + n.ToString(CultureInfo.InvariantCulture) + " " +
            n.ToString(CultureInfo.InvariantCulture) + "\n");

        output.Write(header, 0, header.Length);
        output.Write(bitmap, 0, bitmap.Length);
        output.Flush();
    }
}
